// ---------------------------------------------------------------------------
// v4: skip the carriage-return normalisation in Lexer.lex when the input
// holds no '\r' (1/720 practice docs do). String.replace with no match
// returns its input unchanged, and /\r\n|\r/g cannot match without '\r',
// so this is exactly equivalent, just without the regex scan over the
// whole document. Micro-benched: 0.3ms vs 3.2ms per parse-all.
// (A verbatim copy of Lexer.lex with only that guard added.)
// ---------------------------------------------------------------------------
O.prototype.lex = function (src) {
  if (src.includes('\r')) src = src.replace(T.carriageReturn, '\n');
  this.blockTokens(src, this.tokens);
  for (let t = 0; t < this.inlineQueue.length; t++) {
    const n = this.inlineQueue[t];
    this.state.inRawBlock = false;
    this.inlineTokens(n.src, n.tokens);
  }
  this.inlineQueue = [];
  return this.tokens;
};

// Faithful reimplementation of Lexer#t, with the per-token method calls
// replaced by a first-char dispatch. Each tokenizer method's rule is
// anchored and starts with a fixed first character, so the dispatch is
// exact: a method is only called when its first character matches.
// maskedSrc is the unmasked src (the fast path never has emphasis).
// Note: br also matches a backslash-newline (its regex is
// /^( {2,}|\\\\)\n.../), so the backslash branch tries br after escape.
function fastInlineTokens(lexer, src, maskedSrc, tokens) {
  const tz = lexer.tokenizer;
  const extInline = lexer.options.extensions?.inline;
  const extStartInline = lexer.options.extensions?.startInline;
  let s = false; // previous token was inline text
  let r = ''; // last char of previous text token ("" unless s)
  let o = Infinity; // previous remaining length (infinite-loop guard)
  let e = src;
  const n = tokens;
  for (; e;) {
    if (e.length < o) o = e.length;
    else { lexer.infiniteLoopError(e.charCodeAt(0)); break; }
    if (!s) r = '';
    s = false;
    let i;
    if (extInline?.some((p) => (i = p.call({ lexer }, e, n))
      ? (e = e.substring(i.raw.length), n.push(i), true) : false)) continue;

    const c = e.charCodeAt(0);
    // escape: first char backslash. br also matches a backslash-newline,
    // so try br after escape fails.
    if (c === 92) {
      i = tz.escape(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
      i = tz.br(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    } else if (c === 60) { // '<': tag, then autolink
      i = tz.tag(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
      i = tz.autolink(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    } else if (c === 91 || c === 33) { // '[' or '!': link, then reflink
      i = tz.link(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
      i = tz.reflink(e, lexer.tokens.links);
      if (i) {
        e = e.substring(i.raw.length);
        const p = n.at(-1);
        if (i.type === 'text' && p?.type === 'text') { p.raw += i.raw; p.text += i.text; }
        else n.push(i);
        continue;
      }
    } else if (c === 96) { // backtick: codespan
      i = tz.codespan(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    } else if (c === 32) { // space: br
      i = tz.br(e);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    } else if (c === 42 || c === 95) { // '*' or '_': emStrong
      i = tz.emStrong(e, maskedSrc, r);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    } else if (c === 126) { // '~': del
      i = tz.del(e, maskedSrc, r);
      if (i) { e = e.substring(i.raw.length); n.push(i); continue; }
    }
    // url (only outside a link), then the text fallback.
    if (!lexer.state.inLink && (i = tz.url(e))) {
      e = e.substring(i.raw.length); n.push(i); continue;
    }
    let l = e;
    if (extStartInline) {
      let p = Infinity;
      const h = e.slice(1);
      let u;
      extStartInline.forEach((d) => {
        u = d.call({ lexer }, h);
        if (typeof u === 'number' && u >= 0) p = Math.min(p, u);
      });
      if (p < Infinity && p >= 0) l = e.substring(0, p + 1);
    }
    if (i = tz.inlineText(l)) {
      e = e.substring(i.raw.length);
      if (i.raw.slice(-1) !== '_') r = i.raw.slice(-1);
      s = true;
      const p = n.at(-1);
      if (p?.type === 'text') { p.raw += i.raw; p.text += i.text; }
      else n.push(i);
      continue;
    }
    if (e) { lexer.infiniteLoopError(e.charCodeAt(0)); break; }
  }
  return n;
}

// ---------------------------------------------------------------------------
// v6 step 4: skip the emphasis mask when it cannot change anything.
// maskSrcOriginal hides `*`/`_`/`~` delimiters that sit inside a code
// span, a link span (label, url or title), an html span, or a backslash
// escape, so the emphasis scanner does not treat them as delimiters.
// When no delimiter sits inside such a span (and none is escaped),
// the masked string behaves exactly like the original for emStrong/del:
//   - delimiter runs themselves are only `*`/`_`/`~`, never span chars,
//     so a delimiter outside a span sees the same neighbours;
//   - a span's edge chars are punctuation in both forms (link '['/']'
//     vs ')' , code '`' vs '`', html '<'/'>' vs ']', escape '\x' vs
//     '++'), so the flanking class of an adjacent delimiter, the
//     punctuation/alphanumeric tests in emStrong, and the closer-scan
//     cache (fe) are all unchanged;
//   - all three replaces preserve string length, so indices align.
// maskNeeded() is conservative: any doubt returns true (run the mask).
// It scans the run once with indexOf jumps (no regex), tracking code
// spans (closing run must equal the opening run, as in the regex),
// link spans (bracket-depth counting with escape + code-span skips,
// then the (...) url or [...] ref part), html spans ('<' to next '>'),
// and escapes. Delimiters are checked with native indexOf inside each
// protected region.
// ---------------------------------------------------------------------------

// True when src[a..b) holds '*', '_' or '~'.
function hasDelim(src, a, b) {
  let p = src.indexOf('*', a);
  if (p !== -1 && p < b) return true;
  p = src.indexOf('_', a);
  if (p !== -1 && p < b) return true;
  p = src.indexOf('~', a);
  return p !== -1 && p < b;
}

// End index (exclusive) of the code span starting at the backtick run
// at `pos`, or -1 when the run is bare (no closing run of equal length).
// Mirrors the code-span alternative of the mask regexes
// (`^(`+)([^`]|[^`][\s\S]*?[^`])\1(?!`)`): the content may contain
// backtick runs SHORTER than the opening run (the lazy middle grows
// past them), and the closing run is the FIRST run whose length EQUALS
// the opening run. A run LONGER than the opening run can never close:
// `\1` there would be followed by a backtick ((?!`) fails) or, at its
// tail, preceded by a backtick (the trailing [^`] of the content fails).
// So runs of any other length are skipped as content.
function codeSpanEnd(src, pos) {
  const n = src.length;
  let j = pos;
  while (j < n && src.charCodeAt(j) === 96) j++;
  const open = j - pos;
  let k = j;
  for (;;) {
    k = src.indexOf('`', k);
    if (k < 0) return -1;
    let m = k;
    while (m < n && src.charCodeAt(m) === 96) m++;
    if (m - k === open) return m;
    k = m; // run of other length: part of the content, keep scanning
  }
}

// End index (exclusive) of the link span starting at the '[' at `pos`,
// or -1 when there is no link span (label never closes). The protected
// region covers the label plus, when present, the (...) url part (to
// its matching ')') or the [...] ref part. Bracket depth is counted
// with backslash escapes and code spans skipped, mirroring the label
// pattern of the mask regexes. Over-approximates: a label is protected
// even when its ref is not a defined link (the mask would then be a
// no-op for it, so protecting it only costs speed, never correctness).
// Scans with native indexOf jumps to the next interesting char instead
// of a per-character loop (labels and urls are long in docs).
function linkSpanEnd(src, pos) {
  const n = src.length;
  let depth = 0;
  let i = pos;
  for (;;) {
    let next = -1;
    let p = src.indexOf('[', i);
    if (p !== -1) next = p;
    p = src.indexOf(']', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    p = src.indexOf('`', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    p = src.indexOf('\\', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    if (next === -1) return -1;
    i = next;
    const c = src.charCodeAt(i);
    if (c === 92) { i += 2; continue; } // escape: skip next char
    if (c === 96) {
      const end = codeSpanEnd(src, i);
      if (end < 0) { i++; continue; }
      i = end;
      continue;
    }
    if (c === 91) { depth++; i++; continue; }
    // c === 93 (']'): label closes when depth returns to 0
    depth--;
    i++;
    if (depth !== 0) continue;
    // label closed at i; extend over (...) url or [...] ref part
    if (i < n && src.charCodeAt(i) === 40) {
      let d = 0;
      let j = i;
      for (;;) {
        let nx = -1;
        let q = src.indexOf('(', j);
        if (q !== -1) nx = q;
        q = src.indexOf(')', j);
        if (q !== -1 && (nx === -1 || q < nx)) nx = q;
        q = src.indexOf('\\', j);
        if (q !== -1 && (nx === -1 || q < nx)) nx = q;
        if (nx === -1) return i; // unbalanced parens: protect label alone
        j = nx;
        const cc = src.charCodeAt(j);
        if (cc === 92) { j += 2; continue; }
        if (cc === 40) { d++; j++; continue; }
        d--;
        j++;
        if (d === 0) return j;
      }
    }
    if (i < n && src.charCodeAt(i) === 91) {
      // ref part: reuse the label scan from here
      const refEnd = linkSpanEnd(src, i);
      return refEnd < 0 ? i : refEnd;
    }
    return i; // nolink [...]: protect the label alone
  }
}

// True when the emphasis mask could change emStrong/del behaviour for
// this run: some delimiter sits inside a masked span or is escaped.
// Cheap necessary condition first: a delimiter can only be hidden
// inside a span if some delimiter occurs at or after the first
// span-start char (a delimiter before every span-start sits outside
// all spans, since spans begin at span-start chars).
function maskNeeded(src) {
  const n = src.length;
  let firstSpan = -1;
  let p = src.indexOf('\\', 0);
  if (p !== -1) firstSpan = p;
  p = src.indexOf('`', 0);
  if (p !== -1 && (firstSpan === -1 || p < firstSpan)) firstSpan = p;
  p = src.indexOf('[', 0);
  if (p !== -1 && (firstSpan === -1 || p < firstSpan)) firstSpan = p;
  p = src.indexOf('<', 0);
  if (p !== -1 && (firstSpan === -1 || p < firstSpan)) firstSpan = p;
  if (firstSpan === -1) return false;
  if (src.indexOf('*', firstSpan) === -1 && src.indexOf('_', firstSpan) === -1 &&
      src.indexOf('~', firstSpan) === -1) return false;
  let i = 0;
  while (i < n) {
    // Next span-start char among \ ` [ < (native indexOf jumps).
    let next = -1;
    p = src.indexOf('\\', i);
    if (p !== -1) next = p;
    p = src.indexOf('`', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    p = src.indexOf('[', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    p = src.indexOf('<', i);
    if (p !== -1 && (next === -1 || p < next)) next = p;
    if (next === -1) return false;
    i = next;
    const c = src.charCodeAt(i);
    if (c === 92) { // backslash escape
      const d = src.charCodeAt(i + 1);
      if (d === 42 || d === 95 || d === 126) return true;
      i += 2;
      continue;
    }
    if (c === 96) { // code span
      const end = codeSpanEnd(src, i);
      if (end < 0) {
        // Bare run: skip the whole run (the mask's bare `+ leaves it).
        while (i < n && src.charCodeAt(i) === 96) i++;
        continue;
      }
      if (hasDelim(src, i, end)) return true;
      i = end;
      continue;
    }
    if (c === 60) { // '<' html span: to the next '>'
      const gt = src.indexOf('>', i + 1);
      if (gt < 0) { i++; continue; }
      if (hasDelim(src, i + 1, gt)) return true;
      i = gt + 1;
      continue;
    }
    // '[' link span
    const end = linkSpanEnd(src, i);
    if (end < 0) { i++; continue; }
    if (hasDelim(src, i, end)) return true;
    i = end;
  }
  return false;
}

// ---------------------------------------------------------------------------
// v6 step 2: manual paragraph scan. The GFM paragraph regex
// /^([^\n]+(?:\n(?!hr|heading|blockquote|fences|list|html|table|[ \t]+\n)[^\n]+)*)/
// (normal mode: same minus the table alternative) re-runs its per-line
// negative lookahead over every continuation line. The scan below walks
// lines with indexOf and tests each line with char checks that are
// exactly the regex's alternatives:
//   - blank line (empty, or spaces/tabs only followed by \n) stops;
//     a spaces-only line at EOF is INCLUDED (the lookahead needs \n).
//   - hr: <=3 spaces, 3+ of one of - _ * with spaces/tabs between.
//   - heading: <=3 spaces, 1-6 #, then whitespace or EOL.
//   - blockquote: <=3 spaces then '>'.
//   - fences: <=3 spaces, 3+ backticks with no further backtick on the
//     line, or 3+ tildes.
//   - list: <=3 spaces, *+- or "1."/"1)", then spaces/tabs, then a
//     non-space/tab char on the line.
//   - html: '<' after <=3 spaces -> the paragraph's html pattern is
//     tested on the remaining source (rare; the regex decides).
//   - table (GFM only): the line plus the NEXT line form a table
//     header+delimiter; gated by a necessary-condition char pre-check
//     on the next line, then the table regex itself decides.
// Differentially verified vs v4 on the 720 practice cases + fuzz.
// ---------------------------------------------------------------------------

// Paragraph's html lookahead pattern (same source as the GFM paragraph
// regex's html alternative; K is marked's block-tag list).
const PARA_HTML_RE = new RegExp(`^ {0,3}(?:</?(?:${K})(?: +|\n|/?>)|<(?:(?:script|pre|style|textarea)(?:[\\s>]|$)|!--)|<\\?|<![A-Za-z]|<!\\[CDATA\\[)`);

// Necessary condition for the next line to be a GFM table delimiter:
// <=3 leading spaces, only space | : - chars, at least one '-'.
function tableDelimPrecheck(src, pos, eol) {
  let i = pos;
  let sp = 0;
  while (i < eol && src.charCodeAt(i) === 32 && sp < 3) { i++; sp++; }
  if (i < eol && src.charCodeAt(i) === 32) return false;
  let hasDash = false;
  for (; i < eol; i++) {
    const c = src.charCodeAt(i);
    if (c === 45) hasDash = true;
    else if (c !== 124 && c !== 58 && c !== 32) return false;
  }
  return hasDash;
}

// Does the line at [pos, eol) start a block that ends a paragraph?
// `nextEol` is the end of the FOLLOWING line (-1 when there is none).
function lineStartsBlock(src, pos, eol, nextPos, nextEol, checkTable) {
  let i = pos;
  let sp = 0;
  while (i < eol && src.charCodeAt(i) === 32 && sp < 3) { i++; sp++; }
  if (i >= eol) return false;
  if (src.charCodeAt(i) === 32) {
    // >3 leading spaces: no hr/heading/blockquote/fences/list/html
    // start, but the line can still be a table header (header allows
    // any indent), so fall through to the table check below.
  } else {
    const c = src.charCodeAt(i);
    if (c === 62) return true; // >
    if (c === 35) { // # heading: 1-6 #, then whitespace or EOL
      let j = i;
      let cnt = 0;
      while (j < eol && src.charCodeAt(j) === 35 && cnt < 7) { j++; cnt++; }
      if (cnt <= 6) {
        if (j >= eol) return true;
        const c2 = src.charAt(j);
        if (c2 === ' ' || c2 === '\t' || /\s/.test(c2)) return true;
      }
      // 7+ #'s or non-space after #'s: not a heading; may be a table header
    } else if (c === 96 || c === 126) { // ` or ~ fences
      let j = i;
      while (j < eol && src.charCodeAt(j) === c) j++;
      if (j - i >= 3) {
        if (c === 126) return true;
        let more = false;
        for (let k = j; k < eol; k++) if (src.charCodeAt(k) === 96) { more = true; break; }
        if (!more) return true;
      }
    } else if (c === 45 || c === 95 || c === 42) { // - _ * : hr, else list
      let j = i;
      let count = 0;
      while (j < eol) {
        const cc = src.charCodeAt(j);
        if (cc === c) { count++; j++; }
        else if (cc === 32 || cc === 9) j++;
        else break;
      }
      if (count >= 3 && j >= eol) return true;
      if (c === 42 || c === 45) { // * - list bullet
        const after = i + 1 < eol ? src.charCodeAt(i + 1) : -1;
        if (after === 32 || after === 9) {
          let k = i + 1;
          while (k < eol && (src.charCodeAt(k) === 32 || src.charCodeAt(k) === 9)) k++;
          if (k < eol) return true;
        }
      }
    } else if (c === 43) { // + list bullet
      const after = i + 1 < eol ? src.charCodeAt(i + 1) : -1;
      if (after === 32 || after === 9) {
        let k = i + 1;
        while (k < eol && (src.charCodeAt(k) === 32 || src.charCodeAt(k) === 9)) k++;
        if (k < eol) return true;
      }
    } else if (c === 49) { // '1' ordered list bullet "1." / "1)"
      const d = i + 1 < eol ? src.charCodeAt(i + 1) : -1;
      if (d === 46 || d === 41) {
        const after = i + 2 < eol ? src.charCodeAt(i + 2) : -1;
        if (after === 32 || after === 9) {
          let k = i + 2;
          while (k < eol && (src.charCodeAt(k) === 32 || src.charCodeAt(k) === 9)) k++;
          if (k < eol) return true;
        }
      }
    } else if (c === 60) { // < html: let the regex decide (rare)
      if (PARA_HTML_RE.test(src.slice(pos))) return true;
    }
  }
  if (checkTable && nextPos >= 0 && nextEol > nextPos) {
    // A table starts here iff this line + the next line match the table
    // regex; the pre-check is necessary for the delimiter line.
    if (tableDelimPrecheck(src, nextPos, nextEol)) return xe.test(src.slice(pos));
  }
  return false;
}

// End index (exclusive) of the paragraph starting at src[0], i.e. the
// same extent the GFM/normal paragraph regex would match. Returns -1
// when the regex could not match at all (first line empty).
function paragraphExtent(src, checkTable) {
  const n = src.length;
  if (n === 0 || src.charCodeAt(0) === 10) return -1;
  let nl = src.indexOf('\n');
  if (nl < 0) return n;
  let end = nl;
  let pos = nl + 1;
  while (pos <= n) {
    let eol = src.indexOf('\n', pos);
    if (eol < 0) eol = n;
    // blank line? empty, or spaces/tabs only followed by \n
    let blank = pos >= eol;
    if (!blank) {
      let allSpace = true;
      for (let i = pos; i < eol; i++) {
        const cc = src.charCodeAt(i);
        if (cc !== 32 && cc !== 9) { allSpace = false; break; }
      }
      blank = allSpace && eol < n;
    }
    if (blank) break;
    let nextPos = -1, nextEol = -1;
    if (eol < n) {
      nextPos = eol + 1;
      nextEol = src.indexOf('\n', nextPos);
      if (nextEol < 0) nextEol = n;
    }
    if (lineStartsBlock(src, pos, eol, nextPos, nextEol, checkTable)) break;
    end = eol;
    if (eol >= n) break;
    pos = eol + 1;
  }
  return end;
}

const _paragraphOriginal = _.prototype.paragraph;
_.prototype.paragraph = function (src) {
  // Pedantic uses a different paragraph regex; custom startBlock
  // extensions can truncate the input. Both fall back to the original.
  if (this.options.pedantic || this.options.extensions?.startBlock) {
    return _paragraphOriginal.call(this, src);
  }
  const end = paragraphExtent(src, this.options.gfm);
  if (end < 0) return undefined;
  const text = src.slice(0, end);
  return { type: 'paragraph', raw: text, text, tokens: this.lexer.inline(text) };
};
